   587→  private typeLines(lines: string[], delay = 40, color = '#00ff41'): Promise<void> {
   588→    return lines.reduce(
   589→      (p, line) => p.then(() => this.typeLine(line, delay, color)),
   590→      Promise.resolve()
   591→    );
