   593→
   594→  private typeLine(text: string, charDelay = 40, color = '#00ff41'): Promise<void> {
   595→    return new Promise(resolve => {
   596→      if (!this.scene.isActive() || this.skipTerminal) { resolve(); return; }
   597→
   598→      // 최대 6줄 유지 (스크롤 효과)
   599→      if (this.terminalTexts.length >= 6) {
   600→        this.terminalTexts.shift()?.destroy();
   601→        this.terminalTexts.forEach((t, i) => t.setY(276 + i * 22));
   602→      }
   603→
   604→      const y = 276 + this.terminalTexts.length * 22;
   605→      const t = this.add.text(24, y, '', {
   606→        fontSize: '13px', color, fontFamily: 'monospace',
   607→      });
   608→      this.terminalTexts.push(t);
   609→
   610→      let i = 0;
   611→      const ev = this.time.addEvent({
   612→        delay: charDelay,
   613→        repeat: text.length,
   614→        callback: () => {
   615→          if (!this.scene.isActive() || this.skipTerminal) { ev.destroy(); resolve(); return; }
   616→          t.setText(text.substring(0, i + 1));
   617→          i++;
   618→          if (i > text.length) { ev.destroy(); resolve(); }
   619→        },
   620→      });
   621→    });
   622→  }
   623→
   624→  private progressBar(duration: number, color = '#00ff41'): Promise<void> {
   625→    return new Promise(resolve => {
   626→      if (!this.scene.isActive() || this.skipTerminal) { resolve(); return; }
   627→
   628→      if (this.terminalTexts.length >= 6) {
   629→        this.terminalTexts.shift()?.destroy();
   630→        this.terminalTexts.forEach((t, i) => t.setY(276 + i * 22));
   631→      }
   632→
   633→      const y = 276 + this.terminalTexts.length * 22;
   634→      const bar = this.add.text(24, y, '> [          ]  0%', {
   635→        fontSize: '13px', color, fontFamily: 'monospace',
   636→      });
   637→      this.terminalTexts.push(bar);
   638→
   639→      let step = 0;
   640→      const steps = 10;
   641→      const ev = this.time.addEvent({
   642→        delay: duration / steps,
   643→        repeat: steps - 1,
   644→        callback: () => {
   645→          step++;
   646→          bar.setText(`> [${'█'.repeat(step)}${' '.repeat(steps - step)}] ${step * 10}%`);
   647→          if (this.skipTerminal || step >= steps) { ev.destroy(); resolve(); }
   648→        },
   649→      });
   650→    });
   651→  }
   652→
   653→  private sleep(ms: number): Promise<void> {
   654→    return new Promise(resolve => {
   655→      if (!this.scene.isActive() || this.skipTerminal) { resolve(); return; }
   656→      this.time.delayedCall(ms, resolve);
   657→    });
   658→  }
