   392→  private showRevealCard(pulled: PulledCharacter, def: CharacterDef) {
   393→    const gColor = GRADE_COLORS[pulled.grade] ?? 0xffffff;
   394→
   395→    // ── 배경: 사이버 우주 이미지 + 등급 컬러 헤이즈 ──
   396→    if (this.textures.exists('gacha_background')) {
   397→      const bg = this.add.image(200, 300, 'gacha_background');
   398→      bg.setDisplaySize(400, 600);
   399→    } else {
   400→      this.add.rectangle(200, 300, 400, 600, 0x050510);
   401→    }
   402→    // 어두운 오버레이 (가독성 확보)
   403→    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.5);
   404→    // 등급 컬러 헤이즈 (중앙 중심 방사)
   405→    this.add.circle(200, 260, 200, gColor, 0.08);
   406→    this.add.circle(200, 260, 120, gColor, 0.06);
   407→
   408→    // 배경 글로우 (캐릭터 뒤 빛)
   409→    const glow = this.add.circle(200, 255, 150, gColor, 0.0).setAlpha(0);
   410→    this.tweens.add({
   411→      targets: glow, alpha: 1,
   412→      scaleX: { from: 0.3, to: 1.3 }, scaleY: { from: 0.3, to: 1.3 },
   413→      duration: 600, ease: 'Back.easeOut',
   414→    });
   415→
   416→    // 캐릭터 이미지
   417→    const img = this.add.image(200, 240, def.imageKey).setAlpha(0);
   418→    img.setDisplaySize(130, 205);
   419→    this.tweens.add({
   420→      targets: img, alpha: 1, y: { from: 268, to: 240 },
   421→      duration: 500, ease: 'Back.easeOut', delay: 150,
   422→    });
   423→
   424→    // 등급 라벨
   425→    const gradeText = this.add.text(200, 388, pulled.grade, {
   426→      fontSize: '18px', color: def.gradeColor, fontStyle: 'bold',
   427→      stroke: '#000', strokeThickness: 4, fontFamily: 'monospace',
   428→    }).setOrigin(0.5).setAlpha(0);
   429→    this.tweens.add({ targets: gradeText, alpha: 1, duration: 300, delay: 400 });
   430→
   431→    // 캐릭터 이름
   432→    const nameText = this.add.text(200, 424, def.name, {
   433→      fontSize: '34px', color: '#ffffff', fontStyle: 'bold',
   434→      stroke: '#000000', strokeThickness: 6,
   435→    }).setOrigin(0.5).setAlpha(0);
   436→    this.tweens.add({
   437→      targets: nameText, alpha: 1, y: { from: 442, to: 424 },
   438→      duration: 400, ease: 'Back.easeOut', delay: 500,
   439→    });
   440→
   441→    // NEW! 배지
   442→    if (pulled.isNew) {
   443→      const badge = this.add.text(325, 145, ' NEW! ', {
   444→        fontSize: '15px', color: '#ffff00', fontStyle: 'bold',
   445→        backgroundColor: '#cc0000', stroke: '#000', strokeThickness: 2,
   446→      }).setOrigin(0.5).setAlpha(0).setScale(0);
   447→      this.tweens.add({
   448→        targets: badge, alpha: 1, scaleX: 1, scaleY: 1,
   449→        duration: 300, ease: 'Back.easeOut', delay: 650,
   450→      });
   451→    }
   452→
   453→    // 탭 안내
   454→    const isLast = this.revealIndex >= this.pullResults.length - 1;
   455→    const hint = isLast
   456→      ? 'TAP → RESULTS'
   457→      : `TAP → NEXT  (${this.revealIndex + 1}/${this.pullResults.length})`;
   458→    const tapHint = this.add.text(200, 562, hint, {
   459→      fontSize: '13px', color: '#555555', fontFamily: 'monospace',
   460→    }).setOrigin(0.5);
   461→    this.tweens.add({
   462→      targets: tapHint, alpha: { from: 0.3, to: 1 }, duration: 600, yoyo: true, repeat: -1,
   463→    });
   464→
   465→    // 탭 진행 (700ms 디바운스)
   466→    this.time.delayedCall(700, () => {
   467→      if (!this.scene.isActive()) return;
   468→
   469→      let advanced = false;
   470→      const advance = () => {
   471→        if (advanced) return;
   472→        advanced = true;
   473→        this.input.off('pointerdown', advance);
   474→        this.tweens.killAll();
   475→        this.time.removeAllEvents();
   476→        this.revealIndex++;
   477→        this.showNextReveal();
   478→      };
   479→
   480→      this.input.on('pointerdown', advance);
   481→
   482→      // 10뽑기는 3.5초 자동 진행
   483→      if (this.pullResults.length > 1) {
   484→        this.time.delayedCall(3500, () => {
   485→          if (this.scene.isActive()) advance();
   486→        });
   487→      }
   488→    });
   489→  }
