   495→  private showSummary() {
   496→    this.clearUI();
   497→    if (this.textures.exists('gacha_background')) {
   498→      this.add.image(200, 300, 'gacha_background').setDisplaySize(400, 600);
   499→    } else {
   500→      this.add.rectangle(200, 300, 400, 600, 0x060612);
   501→    }
   502→    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.55);
   503→
   504→    this.add.text(200, 38, '[ EXTRACTION COMPLETE ]', {
   505→      fontSize: '17px', color: '#00ff41', fontStyle: 'bold', fontFamily: 'monospace',
   506→    }).setOrigin(0.5);
   507→
   508→    // 결과 카드 그리드
   509→    const total = this.pullResults.length;
   510→    const cols = Math.min(total, 5);
   511→    const cardW = 64, cardH = 84, gapX = 8, gapY = 12;
   512→    const totalW = cols * cardW + (cols - 1) * gapX;
   513→    const startX = (400 - totalW) / 2 + cardW / 2;
   514→    const startY = total > 5 ? 130 : 175;
   515→
   516→    this.pullResults.forEach((pulled, i) => {
   517→      const def = getCharacterDef(pulled.id);
   518→      const col = i % 5;
   519→      const row = Math.floor(i / 5);
   520→      const x = startX + col * (cardW + gapX);
   521→      const y = startY + row * (cardH + gapY);
   522→      const gColorInt = parseInt(def.gradeColor.replace('#', ''), 16);
   523→
   524→      const bg  = this.add.rectangle(x, y, cardW, cardH, 0x111122).setStrokeStyle(1, gColorInt).setAlpha(0);
   525→      const img = this.add.image(x, y - 8, def.imageKey).setDisplaySize(cardW - 19, cardH - 22).setAlpha(0);
   526→      const nm  = this.add.text(x, y + cardH / 2 - 10, def.name, { fontSize: '9px', color: '#cccccc' }).setOrigin(0.5).setAlpha(0);
   527→
   528→      if (pulled.isNew) {
   529→        this.add.text(x + cardW / 2, y - cardH / 2 + 2, 'NEW', {
   530→          fontSize: '8px', color: '#ffff00', backgroundColor: '#aa0000', padding: { x: 2, y: 1 },
   531→        }).setOrigin(1, 0).setAlpha(0);
   532→      }
   533→
   534→      this.tweens.add({ targets: [bg, img, nm], alpha: 1, duration: 200, delay: i * 60 });
   535→    });
   536→
   537→    // 잔여 SKOR
   538→    const skorY = total > 5 ? 350 : 340;
   539→    this.add.text(200, skorY, `잔여 SKOR: ${Math.floor(this.remainingSkor)}`, {
   540→      fontSize: '14px', color: '#00ff41', fontFamily: 'monospace',
   541→    }).setOrigin(0.5);
   542→
   543→    // 한 번 더 / 메인으로 버튼
   544→    const againBtn = this.add.rectangle(200, 445, 260, 52, 0x080818)
   545→      .setStrokeStyle(1, 0x00ff41).setInteractive({ useHandCursor: true });
   546→    this.add.text(200, 445, '한 번 더', {
   547→      fontSize: '19px', color: '#00ff41', fontStyle: 'bold', fontFamily: 'monospace',
   548→    }).setOrigin(0.5);
   549→    againBtn.on('pointerover', () => againBtn.setFillStyle(0x081808));
   550→    againBtn.on('pointerout',  () => againBtn.setFillStyle(0x080818));
   551→    againBtn.on('pointerdown', () => this.buildLobby());
