// 점수 검증용 데이터
private gameStartTime: number = 0;
private phaserStartTime: number = 0; // 씬 시작 시 Phaser 내부 시간 (재시작 시에도 정확한 delta 계산용)
private lastScoreTime: number = 0;   // Date.now() 기반 점수용
private lastCheatCheckTime: number = 0; // timeScale 감지용
