    this.diamondPoops.add(diamondPoop, true);
    // console.log(`[다이아똥] diamondPoops 그룹에 추가 완료. 그룹 크기: ${this.diamondPoops.getLength()}`);

    // 일반 똥보다 느린 속도로 설정 (난이도에 따라, 설정 기반)
